def transform(g):
    h, w = len(g), len(g[0])
    seen, comps = set(), []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack, cells = [(r, c)], []
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and g[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((color, cells))
    top = min(min(y for y, x in cells) for _, cells in comps)
    out = [[0] * w for _ in range(h)]
    for color, cells in comps:
        shift = top - min(y for y, x in cells)
        for y, x in cells:
            out[y + shift][x] = color
    return out
